/**
 * UUIDv7 (RFC 9562) generator for `event_id`, `session_id` and `batch_id`.
 *
 * Layout: 48-bit Unix ms timestamp | version 7 | 12-bit counter (rand_a) | variant 10 | 62 random bits.
 * The 12-bit `rand_a` field is used as a monotonic counter seeded randomly each millisecond, so ids
 * generated by one process sort in creation order even within the same millisecond (RFC 9562 §6.2,
 * method 1). Ordering is a convenience only; the kiosk never relies on id order (`seq` is the order).
 */

/** Fills a byte array with cryptographically strong random values. */
export type RandomBytes = (bytes: Uint8Array<ArrayBuffer>) => void;

const cryptoRandom: RandomBytes = (bytes) => {
  globalThis.crypto.getRandomValues(bytes);
};

const HEX: readonly string[] = Array.from({ length: 256 }, (_, i) =>
  i.toString(16).padStart(2, '0'),
);

/** Stateful UUIDv7 factory (monotonic within the factory). */
export class Uuidv7Generator {
  private lastMs = -1;
  private counter = 0;
  private readonly random: RandomBytes;
  private readonly nowMs: () => number;

  constructor(options: { readonly random?: RandomBytes; readonly nowMs?: () => number } = {}) {
    this.random = options.random ?? cryptoRandom;
    this.nowMs = options.nowMs ?? Date.now;
  }

  /** Next UUIDv7 string (lower-case, hyphenated). */
  next(): string {
    const bytes = new Uint8Array(16);
    this.random(bytes);
    let ms = Math.max(0, Math.floor(this.nowMs()));
    if (ms <= this.lastMs) {
      // Same (or regressed) millisecond: keep the previous timestamp and bump the counter.
      ms = this.lastMs;
      this.counter += 1;
      if (this.counter > 0xfff) {
        // Counter overflow: advance the embedded timestamp by one ms (still monotonic).
        ms += 1;
        this.counter = (bytes[6] ?? 0) & 0x7f;
      }
    } else {
      // New millisecond: random counter start in the lower half so it has room to grow.
      this.counter = (((bytes[6] ?? 0) & 0x07) << 8) | (bytes[7] ?? 0);
    }
    this.lastMs = ms;

    // 48-bit big-endian timestamp. Division keeps precision beyond 32 bits.
    const high = Math.floor(ms / 0x1_0000_0000);
    const low = ms >>> 0;
    bytes[0] = (high >>> 8) & 0xff;
    bytes[1] = high & 0xff;
    bytes[2] = (low >>> 24) & 0xff;
    bytes[3] = (low >>> 16) & 0xff;
    bytes[4] = (low >>> 8) & 0xff;
    bytes[5] = low & 0xff;
    bytes[6] = 0x70 | ((this.counter >>> 8) & 0x0f);
    bytes[7] = this.counter & 0xff;
    bytes[8] = 0x80 | ((bytes[8] ?? 0) & 0x3f);

    let out = '';
    for (let i = 0; i < 16; i += 1) {
      if (i === 4 || i === 6 || i === 8 || i === 10) out += '-';
      out += HEX[bytes[i] ?? 0];
    }
    return out;
  }
}

const defaultGenerator = new Uuidv7Generator();

/** Generate a UUIDv7 with the process-wide monotonic generator. */
export function uuidv7(): string {
  return defaultGenerator.next();
}

/** Matches the contracts' `uuidv7` pattern. */
export const UUIDV7_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

/** Extract the embedded Unix ms timestamp from a UUIDv7. */
export function uuidv7Timestamp(id: string): number {
  const hex = id.replace(/-/g, '').slice(0, 12);
  return Number.parseInt(hex, 16);
}

/** 64-bit hex seed (16 chars) from the platform CSPRNG (ENG-03: the session seed is logged). */
export function randomSeedHex(random: RandomBytes = cryptoRandom): string {
  const bytes = new Uint8Array(8);
  random(bytes);
  let out = '';
  for (const b of bytes) out += HEX[b];
  return out;
}
